struct B {
    int member1;   // Typically 4 bytes, aligned to 4-byte boundary
    char member2;  // 1 byte, aligned to 1-byte boundary; padding may be added after for subsequent members
    // Compiler may insert padding bytes here, e.g., 3 bytes to align the next member to 4 bytes
};  // Implementation note: The total size is at least sizeof(int) + sizeof(char) + padding, and is affected by #pragma pack or alignas specifiers for custom alignment.
